const max_amps_per_phase = 33;

// Fahrzeugzustände lesen
let state_1 = flow.get("vehicle_1_state");
let state_2 = flow.get("vehicle_2_state");

let auto_1_active = (state_1 > 1 && state_1 < 5 && (flow.get("auth_1") || flow.get("auth_off")));
let auto_2_active = (state_2 > 1 && state_2 < 5 && (flow.get("auth_2") || flow.get("auth_off")));
let active_autos = (auto_1_active ? 1 : 0) + (auto_2_active ? 1 : 0);

// Schuko-Strom berechnen
let schuko_L1 = flow.get("I_L1") - (flow.get("SDM1_IL1") + flow.get("SDM2_IL1"));
let schuko_L2 = flow.get("I_L2") - (flow.get("SDM1_IL2") + flow.get("SDM2_IL2"));
let schuko_L3 = flow.get("I_L3") - (flow.get("SDM1_IL3") + flow.get("SDM2_IL3"));


// Reserven pro Phase
let reserve_L1 = max_amps_per_phase - schuko_L1;
let reserve_L2 = max_amps_per_phase - schuko_L2;
let reserve_L3 = max_amps_per_phase - schuko_L3;

let gemeinsame_reserve = Math.floor(Math.min(reserve_L1, reserve_L2, reserve_L3));

// Grundverteilung
let limit_1 = 0;
let limit_2 = 0;

if (active_autos === 2) {
    limit_1 = Math.floor(gemeinsame_reserve / 2);
    limit_2 = Math.floor(gemeinsame_reserve - limit_1);
} else if (auto_1_active) {
    limit_1 = gemeinsame_reserve;
} else if (auto_2_active) {
    limit_2 = gemeinsame_reserve; 
}

// Stromverbrauch der am stärksten belasteten Phase lesen
let sdm1_Lx = Math.max(flow.get("SDM1_IL1"), flow.get("SDM1_IL2"), flow.get("SDM1_IL3"));
let sdm2_Lx = Math.max(flow.get("SDM2_IL1"), flow.get("SDM2_IL2"), flow.get("SDM2_IL3"));

// Dynamische Umverteilung (beide Richtungen)
let ungenutzt_1 = limit_1 - sdm1_Lx;
let ungenutzt_2 = limit_2 - sdm2_Lx;

// Dynamische Umverteilung aktiviert für den Fall dass beide Autos aktiv laden
if ((flow.get("vehicle_1_state") + flow.get("vehicle_2_state")) === 6) {
    if (ungenutzt_1 > 1 && sdm1_Lx > 3) {
        let abgabe = Math.floor(ungenutzt_1);
        limit_1 -= abgabe;
        limit_2 += abgabe;
    } else if (ungenutzt_2 > 1 && sdm2_Lx > 3) {
        let abgabe = Math.floor(ungenutzt_2);
        limit_2 -= abgabe;
        limit_1 += abgabe;
    }
}
//falls ein Auto present und das andere lädt
if ((flow.get("vehicle_1_state") + flow.get("vehicle_2_state")) === 5) {
    //falls beide authorisiert (eins lädt und das andere soll auch laden)
    if(active_autos ===2){
        limit_1 = Math.floor(gemeinsame_reserve / 2);
        limit_2 = Math.floor(gemeinsame_reserve - limit_1);
    }
    //falls Auto 1 authorisiert und Auto 2 nicht
    else if (flow.get("auth_1")) {
        limit_1 = Math.floor(gemeinsame_reserve); 
    }
    //falls Auto 2 authorisiert und Auto 1 nicht
    else if(flow.get("auth_2")){
        limit_2 = Math.floor(gemeinsame_reserve);
    }
}

// Kleine Reserve nach oben beim kleineren Limit um ggf. eine langsame Stromerhöhung zuzulassen
if((limit_1 < limit_2) && (limit_2 >= 1)){
    limit_1 += 1;
    limit_2 -= 1;
}else if((limit_1 > limit_2) && (limit_1 >= 1)){
    limit_1 -= 1;
    limit_2 += 1;
}
// Sicherheitsprüfung: keine Phase > 32 A nach Verteilung
function pruefe(limit1, limit2) {
    let total_L1 = schuko_L1 + limit1 + limit2;
    let total_L2 = schuko_L2 + limit1 + limit2;
    let total_L3 = schuko_L3 + limit1 + limit2;
    return (total_L1 <= max_amps_per_phase &&
            total_L2 <= max_amps_per_phase &&
            total_L3 <= max_amps_per_phase);
}

// Fallback falls nach Umverteilung Grenze gerissen würde
while(!pruefe(limit_1, limit_2)) {
    if(limit_1 > 1){
        limit_1 -= limit_1;
    }
    if(limit_2 > 1){
        limit_2 = gemeinsame_reserve - limit_1;
    }
}

// Endgültige Limits setzen
flow.set("evse_1_optimized", auto_1_active ? Math.min(limit_1, 32) : 0);
flow.set("evse_2_optimized", auto_2_active ? Math.min(limit_2, 32) : 0);

return msg;

